SELECT *
FROM SEMANTIC_VIEW(
    ANALYTICS.SEMANTIC.ECOM_METRICS
    METRICS NET_REVENUE
    WHERE fct_orders.order_date >= '2024-01-01' AND fct_orders.order_date < '2025-01-01'
);

SELECT *
FROM SEMANTIC_VIEW(
    ANALYTICS.SEMANTIC.ECOM_METRICS
    DIMENSIONS country_name
    METRICS NEW_SIGNUPS
);

